namespace py = pybind11;

#include <gnuradio/ofdm/ifft.h>
// pydoc.h is automatically generated in the build directory
#include <ifft_pydoc.h>

void bind_ifft(py::module& m)
{

    using ifft    = gr::ofdm::ifft;


    py::class_<ifft, gr::sync_block, gr::block, gr::basic_block,
        std::shared_ptr<ifft>>(m, "ifft", D(ifft))

        .def(py::init(&ifft::make),
           D(ifft,make)
        )
        



        ;




}








